type Shape = { kind: "circle"; r: number } | { kind: "square"; side: number };

export function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.r ** 2;
    case "square":
      return shape.side ** 2;
    default: {
      // Exhaustiveness check: this branch cannot run, the cast only reads the tag for the message.
      const unreachable: never = shape;
      const kind = (unreachable as any).kind;
      throw new Error("unhandled shape: " + kind);
    }
  }
}

// Listeners take whatever the emitting site passes; `unknown[]` would make every handler a type error.
type Listener = (...args: any[]) => void;

export class Emitter {
  private listeners = new Map<string, Listener[]>();

  on(event: string, listener: Listener): void {
    this.listeners.set(event, [...(this.listeners.get(event) ?? []), listener]);
  }

  emit(event: string, ...args: unknown[]): void {
    for (const listener of this.listeners.get(event) ?? []) listener(...args);
  }
}

